func name(_ n: Int) -> String {
    if n == 1 { return "one" }
    fatalError("unexpected \(n)")
}
print(name(1))

func setVolume(_ v: Int) {
    assert(v >= 0, "negative volume")
    print("volume", v)
}
setVolume(5)

func pick(_ a: [Int], _ i: Int) -> Int {
    precondition(i < a.count, "bad index")
    return a[i]
}
print(pick([4, 5, 6], 1))

